INSERT INTO collection_pages VALUES('c337d05e6b5a732d9a6a6debcbebbe2006323d29f16a9fb03a2d92ca4b78f427','90895388f8b662c462305af33b9ead8b278ba448f1b5dc86655490c0982bd536','{"hasNext":false,"items":[{"author":{"account":{"login":"lisenhuang","providerType":"User"},"email":"lisen8018@gmail.com","name":"Ethan"},"authoredDate":"2026-08-15T07:56:19Z","committedDate":"2026-08-15T07:56:19Z","committer":{"account":{"login":"lisenhuang","providerType":"User"},"email":"lisen8018@gmail.com","name":"Ethan"},"observedAt":"2026-10-09T00:13:16.459Z","repositoryId":1334902864,"sha":"3d4b45fa5e3beeffd8d2883eee4153ce0bccedfa"},{"author":{"account":{"login":"lisenhuang","providerType":"User"},"email":"lisen8018@gmail.com","name":"Ethan"},"authoredDate":"2026-08-15T05:13:55Z","committedDate":"2026-08-15T05:13:55Z","committer":{"account":{"login":"lisenhuang","providerType":"User"},"email":"lisen8018@gmail.com","name":"Ethan"},"observedAt":"2026-10-09T00:13:16.459Z","repositoryId":1334902864,"sha":"847530466d1412338d55201129feb52d4ce8f4bc"},{"author":{"account":{"login":"lisenhuang","providerType":"User"},"email":"lisen8018@gmail.com","name":"Ethan"},"authoredDate":"2026-08-15T03:49:58Z","committedDate":"2026-08-15T03:49:58Z","committer":{"account":{"login":"lisenhuang","providerType":"User"},"email":"lisen8018@gmail.com","name":"Ethan"},"observedAt":"2026-10-09T00:13:16.459Z","repositoryId":1334902864,"sha":"21d188317ddafdfd7a2400733ddc8c6039fa9fdc"},{"author":{"account":{"login":"lisenhuang","providerType":"User"},"email":"lisen8018@gmail.com","name":"Ethan"},"authoredDate":"2026-08-15T01:57:45Z","committedDate":"2026-08-15T01:57:45Z","committer":{"account":{"login":"lisenhuang","providerType":"User"},"email":"lisen8018@gmail.com","name":"Ethan"},"observedAt":"2026-10-09T00:13:16.459Z","repositoryId":1334902864,"sha":"71df3fc3645fb0834d668bc98fd931f45f0a288e"}],"observedAt":"2026-10-09T00:13:16.459Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/97820031?v=4","events_url":"https://api.github.com/users/lisenhuang/events{/privacy}","followers_url":"https://api.github.com/users/lisenhuang/followers","following_url":"https://api.github.com/users/lisenhuang/following{/other_user}","gists_url":"https://api.github.com/users/lisenhuang/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lisenhuang","id":97820031,"login":"lisenhuang","node_id":"U_kgDOBdSdfw","organizations_url":"https://api.github.com/users/lisenhuang/orgs","received_events_url":"https://api.github.com/users/lisenhuang/received_events","repos_url":"https://api.github.com/users/lisenhuang/repos","site_admin":false,"starred_url":"https://api.github.com/users/lisenhuang/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lisenhuang/subscriptions","type":"User","url":"https://api.github.com/users/lisenhuang","user_view_type":"public"},"comments_url":"https://api.github.com/repos/lisenhuang/ai-news/commits/3d4b45fa5e3beeffd8d2883eee4153ce0bccedfa/comments","commit":{"author":{"date":"2026-08-15T07:56:19Z","email":"lisen8018@gmail.com","name":"Ethan"},"comment_count":0,"committer":{"date":"2026-08-15T07:56:19Z","email":"lisen8018@gmail.com","name":"Ethan"},"message":"Make \"Read original\" a text link instead of a pill button\n\nThe pill-shaped button on every card competed with the headline for\nattention, which is backwards: leaving for the publisher''s page is\nnavigation away from the app, not the primary action on the card.\n\nIt is now a plain underlined hyperlink in ink-secondary, with the small\nexternal-link arrow kept so the new-tab behaviour is still signposted.\nVisible size drops from roughly 160x44 to 104x20.\n\nShrinking the visible control does not shrink the tap target. A\n::before overlay inset by -12px on both axes brings the hit area to\nexactly 44x44 -- the accessibility minimum -- without occupying any\nlayout space, so the link reads as text and still behaves like a target\non a phone. The overlay stays in front rather than behind: a negative\nz-index pseudo-element can hand the tap to whatever paints above it.\nIt covers less area than the old pill did, so nothing that previously\nreached the gallery underneath stops reaching it.\n\nAccessible name, href, target and rel are unchanged, so the existing\nStoryCard tests cover it as-is.\n\nVerified: tsc and eslint clean, 129 frontend tests pass, and the\nrendered link measured in headless Chrome against the built container --\nvisible 103.8x20, no background, no border, 0px radius, underline\npresent, hit area inset -12px on both axes.\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"4663efd362c5079edcd9224066dbcb1501ab12cd","url":"https://api.github.com/repos/lisenhuang/ai-news/git/trees/4663efd362c5079edcd9224066dbcb1501ab12cd"},"url":"https://api.github.com/repos/lisenhuang/ai-news/git/commits/3d4b45fa5e3beeffd8d2883eee4153ce0bccedfa","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/97820031?v=4","events_url":"https://api.github.com/users/lisenhuang/events{/privacy}","followers_url":"https://api.github.com/users/lisenhuang/followers","following_url":"https://api.github.com/users/lisenhuang/following{/other_user}","gists_url":"https://api.github.com/users/lisenhuang/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lisenhuang","id":97820031,"login":"lisenhuang","node_id":"U_kgDOBdSdfw","organizations_url":"https://api.github.com/users/lisenhuang/orgs","received_events_url":"https://api.github.com/users/lisenhuang/received_events","repos_url":"https://api.github.com/users/lisenhuang/repos","site_admin":false,"starred_url":"https://api.github.com/users/lisenhuang/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lisenhuang/subscriptions","type":"User","url":"https://api.github.com/users/lisenhuang","user_view_type":"public"},"html_url":"https://github.com/lisenhuang/ai-news/commit/3d4b45fa5e3beeffd8d2883eee4153ce0bccedfa","node_id":"C_kwDOT5EAUNoAKDNkNGI0NWZhNWUzYmVlZmZkOGQyODgzZWVlNDE1M2NlMGJjY2VkZmE","parents":[{"html_url":"https://github.com/lisenhuang/ai-news/commit/847530466d1412338d55201129feb52d4ce8f4bc","sha":"847530466d1412338d55201129feb52d4ce8f4bc","url":"https://api.github.com/repos/lisenhuang/ai-news/commits/847530466d1412338d55201129feb52d4ce8f4bc"}],"sha":"3d4b45fa5e3beeffd8d2883eee4153ce0bccedfa","url":"https://api.github.com/repos/lisenhuang/ai-news/commits/3d4b45fa5e3beeffd8d2883eee4153ce0bccedfa"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/97820031?v=4","events_url":"https://api.github.com/users/lisenhuang/events{/privacy}","followers_url":"https://api.github.com/users/lisenhuang/followers","following_url":"https://api.github.com/users/lisenhuang/following{/other_user}","gists_url":"https://api.github.com/users/lisenhuang/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lisenhuang","id":97820031,"login":"lisenhuang","node_id":"U_kgDOBdSdfw","organizations_url":"https://api.github.com/users/lisenhuang/orgs","received_events_url":"https://api.github.com/users/lisenhuang/received_events","repos_url":"https://api.github.com/users/lisenhuang/repos","site_admin":false,"starred_url":"https://api.github.com/users/lisenhuang/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lisenhuang/subscriptions","type":"User","url":"https://api.github.com/users/lisenhuang","user_view_type":"public"},"comments_url":"https://api.github.com/repos/lisenhuang/ai-news/commits/847530466d1412338d55201129feb52d4ce8f4bc/comments","commit":{"author":{"date":"2026-08-15T05:13:55Z","email":"lisen8018@gmail.com","name":"Ethan"},"comment_count":0,"committer":{"date":"2026-08-15T05:13:55Z","email":"lisen8018@gmail.com","name":"Ethan"},"message":"Show a phone QR code on `make up`, and stop seeding links that 404\n\nThree changes, driven by actually using the app on a phone.\n\n--- Scan-to-open on `make up` ---\n\nThis is a phone-first vertical feed, but getting it onto a phone meant\nfinding the machine''s LAN address by hand and typing it in. `make up` now\nprints both addresses and a QR code for the LAN one; `make qr` reprints\nthem without restarting anything.\n\n- scripts/lan-ip.sh reads the address of whichever interface holds the\n  default route, so it returns the address a phone on the same Wi-Fi can\n  reach rather than a VPN or Docker bridge address. macOS and Linux paths,\n  with fallbacks; prints nothing when the machine has no usable address.\n- scripts/qr.js is a dependency-free QR encoder (byte mode, EC level M,\n  versions 1-10). Written rather than pulled in because `make up` must work\n  with nothing installed but Docker, and neither application should grow a\n  dependency for a terminal nicety. It renders with half-block characters\n  at explicit black-on-white, since a QR printed light-on-dark is inverted\n  and many phone cameras refuse it.\n- scripts/show-address.sh prefers the host''s Node and falls back to the\n  Node already inside the container, so the QR appears even on a machine\n  with no Node at all. Dockerfile copies the script in for that path.\n- Degrades quietly: no LAN address prints localhost alone, no renderer\n  prints both URLs alone. Neither failure breaks `make up`.\n\nVerified by round-tripping the encoder against Apple''s CoreImage QR\ndetector: 172 generated codes decoded back to their exact input, covering\nversions 1-10, all 8 mask patterns and multi-byte UTF-8. The terminal\nrenderer was separately parsed back and matches the encoder matrix exactly,\nquiet zone included.\n\n--- Demo story links no longer 404 ---\n\nReported: tapping \"read the original\" on a demo story opened a not-found\npage, e.g. https://ai.meta.com/blog/multilingual-speech-1600-languages/.\n\nThe demo headlines are invented, so no article exists behind them, but the\nseed wrote plausible-looking article paths anyway. Checking all 28 against\nthe live web: 25 were dead, and two were worse than dead -- the fabricated\narXiv identifiers resolved to real, unrelated papers.\n\nA spec can no longer express a URL. canonical_url is derived from the\nsource''s own homepage_url -- a real catalogue value -- plus a #demo-<slug>\nfragment. Fragments are resolved by the browser and never sent to the\nserver, so appending one cannot break a working link, and the slug keeps\neach row unique without inventing anything. This is the rule the catalogue\nalready applied to feed_url (Contract 7), extended to article URLs.\n\nRe-seeding now also removes demo stories the seed no longer defines,\notherwise the 28 stale rows would outlive this change on any existing\ndeployment -- including the running container. It deletes only rows it can\nprove it own: summary_provider \"seed\", a #demo- URL, or a story whose\nsource has never been fetched (a story is only created downstream of a\nfetch that stamps last_fetched_at, so such a source cannot have contributed\na real one). Confirmed against a container holding 388 ingested stories:\nall 388 survived, and no source had non-demo stories without a fetch on\nrecord.\n\nNew: `bin/rails seeds:check_links` checks every seeded link against the\nlive web, reporting a publisher''s 401/403/429 bot wall separately from a\nreal 404. It skips ingested stories unless ALL_STORIES=true -- those URLs\nare the publisher''s claim, not ours, and there are hundreds of them. It\nmakes real outbound requests, so it is never part of `rails test`.\n\n--- VS Code commit message instructions ---\n\n.vscode/commit-instructions.md defines what a commit message here must\ncontain: why before what, migrations and env vars called out, and how the\nchange was verified. .vscode/settings.json wires it into the Source Control\nview''s generate-message button, with a short inline fallback. .gitignore\nun-ignores both, since ignored files would defeat the point.\n\n--- Verification ---\n\nBackend 302 tests, 1317 assertions, 0 failures. Frontend 129 tests, 0\nfailures. seeds:check_links: 60 checked, 58 ok, 2 bot-walled (Reuters 401,\nVentureBeat 429 -- pre-existing catalogue homepages), 0 broken. Container\nrebuilt from the Dockerfile; feed and health check verified over the LAN\naddress from another device''s perspective.\n\nExisting deployments pick up the link fix automatically -- SEED_ON_BOOT\nre-seeds and prunes. No migration, no new environment variable.\n\nCo-Authored-By: Claude Opus 5 (1M context) <noreply@anthropic.com>","tree":{"sha":"57353d1853d29f2762b1f6daa73f9a9059c3d509","url":"https://api.github.com/repos/lisenhuang/ai-news/git/trees/57353d1853d29f2762b1f6daa73f9a9059c3d509"},"url":"https://api.github.com/repos/lisenhuang/ai-news/git/commits/847530466d1412338d55201129feb52d4ce8f4bc","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/97820031?v=4","events_url":"https://api.github.com/users/lisenhuang/events{/privacy}","followers_url":"https://api.github.com/users/lisenhuang/followers","following_url":"https://api.github.com/users/lisenhuang/following{/other_user}","gists_url":"https://api.github.com/users/lisenhuang/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lisenhuang","id":97820031,"login":"lisenhuang","node_id":"U_kgDOBdSdfw","organizations_url":"https://api.github.com/users/lisenhuang/orgs","received_events_url":"https://api.github.com/users/lisenhuang/received_events","repos_url":"https://api.github.com/users/lisenhuang/repos","site_admin":false,"starred_url":"https://api.github.com/users/lisenhuang/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lisenhuang/subscriptions","type":"User","url":"https://api.github.com/users/lisenhuang","user_view_type":"public"},"html_url":"https://github.com/lisenhuang/ai-news/commit/847530466d1412338d55201129feb52d4ce8f4bc","node_id":"C_kwDOT5EAUNoAKDg0NzUzMDQ2NmQxNDEyMzM4ZDU1MjAxMTI5ZmViNTJkNGNlOGY0YmM","parents":[{"html_url":"https://github.com/lisenhuang/ai-news/commit/21d188317ddafdfd7a2400733ddc8c6039fa9fdc","sha":"21d188317ddafdfd7a2400733ddc8c6039fa9fdc","url":"https://api.github.com/repos/lisenhuang/ai-news/commits/21d188317ddafdfd7a2400733ddc8c6039fa9fdc"}],"sha":"847530466d1412338d55201129feb52d4ce8f4bc","url":"https://api.github.com/repos/lisenhuang/ai-news/commits/847530466d1412338d55201129feb52d4ce8f4bc"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/97820031?v=4","events_url":"https://api.github.com/users/lisenhuang/events{/privacy}","followers_url":"https://api.github.com/users/lisenhuang/followers","following_url":"https://api.github.com/users/lisenhuang/following{/other_user}","gists_url":"https://api.github.com/users/lisenhuang/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lisenhuang","id":97820031,"login":"lisenhuang","node_id":"U_kgDOBdSdfw","organizations_url":"https://api.github.com/users/lisenhuang/orgs","received_events_url":"https://api.github.com/users/lisenhuang/received_events","repos_url":"https://api.github.com/users/lisenhuang/repos","site_admin":false,"starred_url":"https://api.github.com/users/lisenhuang/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lisenhuang/subscriptions","type":"User","url":"https://api.github.com/users/lisenhuang","user_view_type":"public"},"comments_url":"https://api.github.com/repos/lisenhuang/ai-news/commits/21d188317ddafdfd7a2400733ddc8c6039fa9fdc/comments","commit":{"author":{"date":"2026-08-15T03:49:58Z","email":"lisen8018@gmail.com","name":"Ethan"},"comment_count":0,"committer":{"date":"2026-08-15T03:49:58Z","email":"lisen8018@gmail.com","name":"Ethan"},"message":"Add a Makefile so Docker runs with zero configuration\n\n`make up` is now the whole setup: it generates SECRET_KEY_BASE into a\ngitignored root .env (which Compose picks up automatically), builds the image,\nstarts Next.js + Rails + the Solid Queue worker, and blocks until /api/health\nanswers before printing the URL. Nothing has to be copied or edited first.\n\nThe secret is generated once and reused, so it stays stable across rebuilds\nrather than invalidating on every start. `make env` is idempotent and will not\nclobber an existing value.\n\nTargets cover the whole lifecycle — up/start/build/rebuild, down/stop/restart,\nlogs/ps/health, shell/console, seed/reset, ingest/failures, clean/nuke — plus\nlocal (non-Docker) development: install, dev-backend, dev-frontend, dev-jobs,\ntest, lint, and a doctor target that reports the toolchain and whether the\nports are free. `make help` lists them, split by whether Docker is needed.\n\nAlso downgrades the empty-CORS log line from WARN to INFO and rewords it. An\nempty origin list is the *correct* configuration for the single-container\ndeployment, where the browser talks to the same origin and CORS never applies,\nso warning that \"browser clients will be rejected\" was both alarming and\nuntrue there.\n\nVerified from a clean state (no .env, no image, no volume): make up -> ready;\nUI 200; POST /visitors/init and GET /feed return seeded stories through the\nsingle origin; make down + make start preserves the volume and keeps a viewed\nstory excluded; 302 backend tests still pass.","tree":{"sha":"ca097aede1e2070264d7dbf2bc2f81854707e536","url":"https://api.github.com/repos/lisenhuang/ai-news/git/trees/ca097aede1e2070264d7dbf2bc2f81854707e536"},"url":"https://api.github.com/repos/lisenhuang/ai-news/git/commits/21d188317ddafdfd7a2400733ddc8c6039fa9fdc","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/97820031?v=4","events_url":"https://api.github.com/users/lisenhuang/events{/privacy}","followers_url":"https://api.github.com/users/lisenhuang/followers","following_url":"https://api.github.com/users/lisenhuang/following{/other_user}","gists_url":"https://api.github.com/users/lisenhuang/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lisenhuang","id":97820031,"login":"lisenhuang","node_id":"U_kgDOBdSdfw","organizations_url":"https://api.github.com/users/lisenhuang/orgs","received_events_url":"https://api.github.com/users/lisenhuang/received_events","repos_url":"https://api.github.com/users/lisenhuang/repos","site_admin":false,"starred_url":"https://api.github.com/users/lisenhuang/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lisenhuang/subscriptions","type":"User","url":"https://api.github.com/users/lisenhuang","user_view_type":"public"},"html_url":"https://github.com/lisenhuang/ai-news/commit/21d188317ddafdfd7a2400733ddc8c6039fa9fdc","node_id":"C_kwDOT5EAUNoAKDIxZDE4ODMxN2RkYWZkZmQ3YTI0MDA3MzNkZGM4YzYwMzlmYTlmZGM","parents":[{"html_url":"https://github.com/lisenhuang/ai-news/commit/71df3fc3645fb0834d668bc98fd931f45f0a288e","sha":"71df3fc3645fb0834d668bc98fd931f45f0a288e","url":"https://api.github.com/repos/lisenhuang/ai-news/commits/71df3fc3645fb0834d668bc98fd931f45f0a288e"}],"sha":"21d188317ddafdfd7a2400733ddc8c6039fa9fdc","url":"https://api.github.com/repos/lisenhuang/ai-news/commits/21d188317ddafdfd7a2400733ddc8c6039fa9fdc"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/97820031?v=4","events_url":"https://api.github.com/users/lisenhuang/events{/privacy}","followers_url":"https://api.github.com/users/lisenhuang/followers","following_url":"https://api.github.com/users/lisenhuang/following{/other_user}","gists_url":"https://api.github.com/users/lisenhuang/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lisenhuang","id":97820031,"login":"lisenhuang","node_id":"U_kgDOBdSdfw","organizations_url":"https://api.github.com/users/lisenhuang/orgs","received_events_url":"https://api.github.com/users/lisenhuang/received_events","repos_url":"https://api.github.com/users/lisenhuang/repos","site_admin":false,"starred_url":"https://api.github.com/users/lisenhuang/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lisenhuang/subscriptions","type":"User","url":"https://api.github.com/users/lisenhuang","user_view_type":"public"},"comments_url":"https://api.github.com/repos/lisenhuang/ai-news/commits/71df3fc3645fb0834d668bc98fd931f45f0a288e/comments","commit":{"author":{"date":"2026-08-15T01:57:45Z","email":"lisen8018@gmail.com","name":"Ethan"},"comment_count":0,"committer":{"date":"2026-08-15T01:57:45Z","email":"lisen8018@gmail.com","name":"Ethan"},"message":"Add AI News: Rails 8.1 API + Next.js 16 TikTok-style vertical feed\n\nTwo independent applications in one repository, communicating over a\ndocumented JSON API. Every backend route lives under /api so both can be\nserved from a single origin (and a single container), with only /api routed\nto Rails — the same surface a future mobile client will call.\n\nbackend/ — Rails 8.1.3.1, API-only, Ruby 4.0.6, SQLite (primary + queue)\n  * Source / Story / StoryMedia / AnonymousVisitor / StoryView, with the\n    composite indexes the feed keyset and view-exclusion depend on.\n  * Feed::Query: published-only, excludes stories this visitor already viewed\n    (NOT EXISTS), one story per duplicate cluster per batch, keyset pagination\n    over (feed_rank, id) where feed_rank blends recency with a source-tier\n    authority boost.\n  * Idempotent view recording backed by a unique index.\n  * Ingestion pipeline: fetch -> normalize -> deduplicate -> summarize ->\n    publish, plus an hourly Solid Queue recurring fan-out. Configurable\n    Nokogiri RSS/Atom/RDF parser; no generic scraper.\n  * Summarization behind a SummaryProvider interface: a deterministic offline\n    mock by default, with a guarded Anthropic adapter as the boundary.\n  * Internal admin JSON API, disabled entirely unless ADMIN_API_TOKEN is set.\n  * Seeds: the 50-source approved catalogue (Tier 3 journalism inactive\n    pending terms review; feed_url left blank wherever unverified) and 28 demo\n    stories covering every card state, so the app demos with no network.\n\nfrontend/ — Next.js 16.3.1, React 19, TypeScript, Tailwind 4\n  * Native CSS scroll-snap feed; JS only reads position and jumps, so touch\n    swiping never fights the framework. Centred 9:16 column on desktop.\n  * A story counts as viewed only after 1s of continuous >=60% visibility —\n    never merely because it was fetched.\n  * Wheel navigation is rate-limited so a trackpad flick advances exactly one\n    story. Keyboard: down/j, up/k, left/right for galleries.\n  * Three card variants: single image, gallery, and a typography-first\n    no-image card with no empty placeholder. Attribution and a \"Read original\"\n    link are present in all three.\n  * Anonymous identity via an opaque server-issued token in localStorage. No\n    fingerprinting.\n\nVerification: 302 backend tests / 1317 assertions and 129 frontend tests all\npass; the container builds and serves both the UI and /api; 15 real-browser\nchecks (mobile + desktop) pass against both the dev servers and the image.\n\nKnown limitations, the source-attribution rules and the full API reference are\ndocumented in README.md.","tree":{"sha":"32032e9e53ee0aa2907439c38e09d31dff30185f","url":"https://api.github.com/repos/lisenhuang/ai-news/git/trees/32032e9e53ee0aa2907439c38e09d31dff30185f"},"url":"https://api.github.com/repos/lisenhuang/ai-news/git/commits/71df3fc3645fb0834d668bc98fd931f45f0a288e","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/97820031?v=4","events_url":"https://api.github.com/users/lisenhuang/events{/privacy}","followers_url":"https://api.github.com/users/lisenhuang/followers","following_url":"https://api.github.com/users/lisenhuang/following{/other_user}","gists_url":"https://api.github.com/users/lisenhuang/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/lisenhuang","id":97820031,"login":"lisenhuang","node_id":"U_kgDOBdSdfw","organizations_url":"https://api.github.com/users/lisenhuang/orgs","received_events_url":"https://api.github.com/users/lisenhuang/received_events","repos_url":"https://api.github.com/users/lisenhuang/repos","site_admin":false,"starred_url":"https://api.github.com/users/lisenhuang/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/lisenhuang/subscriptions","type":"User","url":"https://api.github.com/users/lisenhuang","user_view_type":"public"},"html_url":"https://github.com/lisenhuang/ai-news/commit/71df3fc3645fb0834d668bc98fd931f45f0a288e","node_id":"C_kwDOT5EAUNoAKDcxZGYzZmMzNjQ1ZmIwODM0ZDY2OGJjOThmZDkzMWY0NWYwYTI4OGU","parents":[],"sha":"71df3fc3645fb0834d668bc98fd931f45f0a288e","url":"https://api.github.com/repos/lisenhuang/ai-news/commits/71df3fc3645fb0834d668bc98fd931f45f0a288e"}],"requestUrl":"https://api.github.com/repos/lisenhuang/ai-news/commits?per_page=100&page=1&sha=3d4b45fa5e3beeffd8d2883eee4153ce0bccedfa&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A23%3A01.568Z"}');
